packages:
  RipulAgent:
    path: ../ripul-ios-sdk

targets:
  RipulApp:
    type: application
    platform: iOS
    sources:
      - Shared
      - iOS
      - path: MemoryService/memory-service.mjs
        type: file
        buildPhase: resources
      # Ripul's own theme, the one file native and web both read (ripul-ios-sdk/docs/theming.md).
      - path: ../theme/ripul-theme.json
        type: file
        buildPhase: resources
      # The loud test document, loadable in Debug builds only (iOS/RipulAppTheme.swift).
      - path: ../theme/ripul-theme-loud.json
        type: file
        buildPhase: resources
      # The trial brand document, loadable in Debug builds only, and the two families it
      # names (theme/fonts/SOURCES.md). The folder is copied whole, licences included.
      - path: ../theme/ripul-theme-brand.json
        type: file
        buildPhase: resources
      - path: ../theme/fonts
        type: folder
        buildPhase: resources
      - path: ../shared/providers.json
        type: file
        buildPhase: resources
      - path: ../shared/autocomplete-categories.json
        type: file
        buildPhase: resources
      - path: StandaloneRuntime
        type: folder
        buildPhase: resources
    preBuildScripts:
      - name: Refuse sheets that are phone-sized on Catalyst
        script: |
          python3 "$SRCROOT/scripts/check_sheet_sizing.py"
        basedOnDependencyAnalysis: false
      - name: Refuse new fonts and colours written at the call site
        script: |
          python3 "$SRCROOT/scripts/check_theme_tokens.py"
        basedOnDependencyAnalysis: false
      - name: Write the theme usage map for the View Explorer
        script: |
          # Which theme tokens each identified element is drawn with, read from the source
          # (ripul-ios-sdk/docs/theming.md, "The View Explorer"). Debug builds only. It never
          # fails a build: without the file the explorer says the map is missing.
          if [ "$CONFIGURATION" = "Debug" ]; then
            python3 "$SRCROOT/scripts/theme_usage_map.py" \
              --out "$TARGET_BUILD_DIR/$UNLOCALIZED_RESOURCES_FOLDER_PATH/ripul-theme-usage.json" \
              || echo "warning: the theme usage map was not written"
          fi
        basedOnDependencyAnalysis: false
      - name: Build bundled standalone interface
        script: |
          # A compile check passes RIPUL_SKIP_STANDALONE_BUILD=1: this step writes into the
          # repository's own StandaloneRuntime folder, so two builds at once would write the
          # same files. Skipped only when a built interface is already there to bundle.
          if [ "${RIPUL_SKIP_STANDALONE_BUILD:-}" = "1" ] && [ -f "$SRCROOT/StandaloneRuntime/popup.html" ]; then
            echo "Standalone interface: using the one already built (RIPUL_SKIP_STANDALONE_BUILD=1)"
            exit 0
          fi
        #if DEBUG && targetEnvironment(macCatalyst)
        // `ripul://debug-image-window` — an image window on a drawn test image,
        // for an agent testing the window without a chat that has an image.
        case "debug-image-window":
            let size = CGSize(width: 600, height: 400)
            let data = UIGraphicsImageRenderer(size: size).pngData { context in
                UIColor.ripul(system: .systemTeal).setFill()
                context.fill(CGRect(origin: .zero, size: size))
            }
            if let launch = try? ImageWindowStore.save(data, name: "Test image") { ImageWindowOpener.open?(launch) }
        #endif
        #if DEBUG
        // `ripul://theme?name=ripul-theme-loud` — switch to another bundled theme
        // document while the app runs (`name=ripul-theme` to go back). Debug only.
        case "theme":
            if let name = URLComponents(url: url, resolvingAgainstBaseURL: false)?
                .queryItems?.first(where: { $0.name == "name" })?.value {
                RipulAppTheme.select(name)
            }
        #endif
        // `ripul://agents` — the Agents list, e.g. for an agent driving the
        // app remotely (devicectl ... launch --payload-url ripul://agents).
        case "agents":
            returnToPlansAfterChat = false
            selectedTab = .agent
            showingSidebar = false
