HEAD is now at d19626c Theme trial: fonts and colours from the Ripul SDK's theme, and a brand look
import CoreText
// Every file that names a theme token needs the SDK; exported once from here.
@_exported import RipulAgent
import SwiftUI

/// The app's two looks. Each is a theme document in the bundle, read by the
/// Ripul SDK, whose accessors (`.ripul(.body)`, `.ripul(.surface)`) every
/// screen takes its fonts and colours from.
enum AppTheme: String, CaseIterable, Identifiable {
    /// The app as it was before it had a theme: the system's fonts and colours.
    case standard
    /// The website's look: its paper and navy, a serif for names and headings.
    case brand

    /// Where the choice is kept. `-theme brand` at launch chooses one too.
    static let key = "theme"

    var id: String { rawValue }

    var title: String {
        switch self {
        case .standard: "Standard"
        case .brand: "Sandsend"
        }
    }

    private var document: String {
        switch self {
        case .standard: "sandsend-default"
        case .brand: "sandsend-brand"
        }
    }

    static var current: AppTheme {
        UserDefaults.standard.string(forKey: key).flatMap(AppTheme.init(rawValue:)) ?? .standard
    }

    /// Call once at launch, before anything is drawn.
    static func install() {
        registerFonts()
        current.apply()
        if let next = Levers.themeThen {
            DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) { next.apply() }
        }
    }

    /// Changes the look of everything on screen, and keeps the choice.
    func apply() {
        UserDefaults.standard.set(rawValue, forKey: Self.key)
        guard let url = Bundle.main.url(forResource: document, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              (try? RipulTheme.adopt(documentData: data)) != nil else {
            RipulTheme.resetToDefaults()
            return
        }
    }

    /// The brand's fonts are files in the bundle (`Fonts/SOURCES.md`).
    private static func registerFonts() {
        for url in Bundle.main.urls(forResourcesWithExtension: "ttf", subdirectory: nil) ?? [] {
            CTFontManagerRegisterFontsForURL(url as CFURL, .process, nil)
        }
    }
}
import SwiftUI
#if DEBUG
import RipulAgent
#endif

extension View {
    /// Names a control `screen.element` so agents and tests can address it.
    /// In a Debug build the Ripul SDK also records the control's exact frame.
    func identified(_ identifier: String) -> some View {
        #if DEBUG
        return uiKitIdentifier(identifier)
        #else
        return accessibilityIdentifier(identifier)
        #endif
    }
}
