import SwiftUI

@main
struct SandsendRetreatsApp: App {
    @AppStorage("onboarded") private var onboarded = false
    @AppStorage("cottage") private var cottageID = ""

    init() {
        AppTheme.install()
        #if DEBUG
        DeveloperConsole.install()
        #endif
    }

    var body: some Scene {
        WindowGroup {
            Group {
                if onboarded, let cottage = Guide.shared.cottage(cottageID) {
                    GuideTabs(cottage: cottage)
                        .transition(.opacity)
                } else {
                    OnboardingView()
                        .transition(.opacity)
                }
            }
            .animation(.smooth, value: onboarded)
            .ripulThemeRoot()
        }
    }
